package com.scamshield.verification;
import com.scamshield.common.domain.*; import com.scamshield.common.repo.*; import org.springframework.stereotype.Service; import java.util.*;
@Service public class VerificationService { private final OfficialNumberRepository numbers; private final PhoneRiskRepository risks; public VerificationService(OfficialNumberRepository n,PhoneRiskRepository r){numbers=n;risks=r;} public Map<String,Object> verify(String raw){if(raw==null)throw new IllegalArgumentException("Phone number is required");String p=raw.replaceAll("[\\s-]","");if(p.matches("^7[0-9]{7}$"))p="+267"+p;if(!p.matches("\\+267[0-9]{8}"))throw new IllegalArgumentException("Valid Botswana phone number required (e.g. +26771111111)"); var n=numbers.findByPhoneNumber(p); var r=risks.findById(p); Map<String,Object> out=new LinkedHashMap<>(); out.put("phoneNumber",p); out.put("status",n.isPresent()?"VERIFIED_PROVIDER_NUMBER":r.map(x->x.level+"_RISK").orElse("UNKNOWN_NUMBER"));out.put("callerIdentityAuthenticated",false); n.ifPresent(x->out.put("provider",x.provider.name)); r.ifPresent(x->{out.put("riskScore",x.score);out.put("level",x.level);out.put("reasons",List.of(x.reasons.split("; ")));out.put("reportCount",x.reportCount);}); return out;} }
